// The session API's types (specs/session.md), generated by `cargo xtask schema` from
// specs/session.schema.json, itself generated from the Rust protocol types. Do not edit.

/** The protocol version these types describe. */
export const PROTOCOL = "2026-10";

/**
 * One thing glave can do with a connected host. Whether an action runs without asking is
 * still for approvals to say (`approvals.md`).
 */
export type Ability = "read" | "push" | "pull_requests" | "issues";

/**
 * Every passkey that signs the person in with a relying party, after a sign-in, for the
 * browser to tell its passkey manager (`PublicKeyCredential.signalAllAcceptedCredentials`),
 * which then hides or deletes the person's others there.
 */
export type AcceptedPasskeys = {
  /** Each passkey's credential id (`allAcceptedCredentialIds`), in base64url. */
  readonly credentials: readonly (string)[];
  /** The relying party's id (`rpId`): the public origin's name, or `localhost`. */
  readonly party: string;
  /** The person's user handle (`userId`), in base64url. */
  readonly user: string;
};

/** The person's answer to an approval. */
export type Answer = "allow_once" | "allow_for_thread" | "deny";

/** A request that failed, as JSON-RPC carries it. */
export type ApiError = {
  readonly code: number;
  readonly data?: ErrorData | null;
  /** What a person is told, in their language where it is the server's own sentence. */
  readonly message: string;
};

/**
 * When an event was recorded, in UTC at millisecond precision. For people only: events are
 * ordered by [`Seq`]. Always written with three fractional digits, such as
 * `2026-10-07T21:14:01.250Z`, so every instant has exactly one spelling.
 */
export type At = string;

/** A file `turn/start` adds to its message: one `file/upload` kept in the thread's project. */
export type AttachedFile = {
  /** Its name, shown with the message and told to the model. */
  readonly name: string;
  readonly sha256: string;
};

/**
 * Whether this server keeps its computer from sleeping on its own while a turn, task or
 * schedule runs (`specs/one-server.md`, owner decision 10).
 */
export type AwakeInfo = {
  readonly kind: "never";
} | {
  readonly kind: "chosen";
  readonly on: boolean;
} | {
  readonly kind: "cannot";
  readonly reason: string;
};

/** Links a tool call to its result: 1 to 128 printable ASCII characters. */
export type CallId = string;

/** What a change did to its file. */
export type ChangeKind = "wrote" | "edited" | "edited_every";

/** A file, with every line its changes added and took out, and each change. */
export type ChangedFile = {
  readonly added: number;
  /** Its changes, in order. */
  readonly changes: readonly (FileChange)[];
  /** Where it is, as the call named it. */
  readonly path: string;
  readonly removed: number;
};

/** Where a folder is checked out: a computer, and the path on it. */
export type Checkout = {
  /** The computer, by the id it keeps across runs. */
  readonly computer: string;
  /** The folder's absolute path there, links resolved. */
  readonly path: string;
};

/** One choice. */
export type Choice = {
  readonly description?: string | null;
  readonly label: string;
};

/**
 * Identifies a command kept running in the background, unique everywhere (UUID v7, minted by
 * the computer it runs on).
 */
export type CommandId = string;

/** Identifies a computer, unique everywhere (UUID v7, minted by the adapter that made it). */
export type ComputerId = string;

/** What kind of computer it is. */
export type ComputerKind = "local" | "worker";

/** The computer a workspace is on. */
export type ComputerRef = {
  readonly id: string;
  readonly kind: ComputerKind;
};

/** A connection's sign-in to its remote MCP server, or a server that asks for one. */
export type ConnectionInfo = {
  /** What the person's settings call the server at that address, when they name one. */
  readonly name?: string | null;
  readonly status: ConnectionStatus;
  /** The MCP server's address: `https://mcp.example.com/mcp`. */
  readonly url: string;
  /** How much it was used, once it is in the person's settings. */
  readonly usage?: Usage | null;
};

/** Whether the person is signed in, and the sign-in still works. */
export type ConnectionStatus = "signed_in" | "expired" | "signed_out";

/**
 * How full a thread's context is: what its conversation last sent and got back, of the window
 * compaction aims for.
 */
export type ContextUse = {
  /**
   * `tokens` of `window`, in whole percent, at most 100. A turn compacts before a request
   * past its threshold (80 unless set).
   */
  readonly percent: number;
  /** The tokens its latest call sent and got back. */
  readonly tokens: number;
  /**
   * The window compaction aims for, in tokens: the configured one, or a smaller one the
   * model stated.
   */
  readonly window: number;
};

/**
 * Identifies one sign-in a person keeps, sealed under a key of its own: a git host
 * (`credential.connected`) or a connection (`connection.connected`).
 */
export type CredentialId = string;

/** A git host the person connected. */
export type CredentialInfo = {
  /**
   * What glave can do with it, from what the host said the token may do; absent when the
   * host did not say, so a client claims nothing.
   */
  readonly can?: readonly (Ability)[] | null;
  readonly forge: Forge;
  /**
   * The token's last four characters, to tell tokens apart; absent for a token too short
   * to show any of.
   */
  readonly hint?: string | null;
  readonly id: CredentialId;
  /** Whom the host said the token is for, when it said. */
  readonly login?: string | null;
  /** Where the host is: `https://github.com`. */
  readonly url: string;
};

/** An ISO 4217 currency code: three uppercase ASCII letters, such as `USD`. */
export type Currency = string;

/**
 * Signing in to GitHub in the browser (its device flow): the person opens `url` and enters
 * `code`, then the client waits on `flow` with `credential/device/poll`.
 */
export type DeviceCode = {
  /** What the person enters on GitHub's page, such as `WDJB-MJHT`. */
  readonly code: string;
  /** Seconds until the code expires. */
  readonly expires_in: number;
  /** Names this sign-in to `credential/device/poll`. */
  readonly flow: string;
  /** GitHub's page where the code is entered. */
  readonly url: string;
};

/** One line of a change. */
export type DiffLine = {
  readonly kind: LineKind;
  readonly text: string;
};

/** What a failure says beyond its sentence, for a client to act on. */
export type ErrorData = {
  readonly failure: Failure;
} | {
  readonly unknown_passkey: UnknownPasskey;
};

/** Identifies one event, unique everywhere. */
export type EventId = string;

/** The kind of a failed model request. */
export type Failure = "refused" | "no_credit" | "unknown_model" | "too_long" | "rate_limited" | "unavailable" | "unreachable" | "silent" | "malformed" | "rejected" | "over_budget";

/**
 * One change to a file: a `write` or an `edit` that finished without an error, as its call
 * asked for it, which the tool applied exactly.
 */
export type FileChange = {
  readonly kind: ChangeKind;
  /**
   * Its lines in order: those kept before it, those taken out, those put in, and those kept
   * after it.
   */
  readonly lines: readonly (DiffLine)[];
};

/** A file the server keeps, as `file/upload` answers it. */
export type FileInfo = {
  /** Its size. */
  readonly bytes: number;
  /** Its media type, such as `image/png`, as what it holds says. */
  readonly media_type: string;
  /** Its name, as the person's computer called it. */
  readonly name: string;
  /** Its content's SHA-256, which `turn/start` names it by. */
  readonly sha256: string;
};

/** Where a folder's files come from. */
export type FolderSource = {
  readonly kind: "repository";
  readonly url: string;
} | {
  readonly kind: "local";
};

/**
 * Which forge a git host runs, as far as glave could tell: what its API and its
 * command-line tool are.
 */
export type Forge = "github" | "gitlab" | "gitea" | "bitbucket" | "other";

/** A thread's latest goal and how far it has come. */
export type GoalProgress = {
  /** Why it ended; `None` while it is active. */
  readonly ended?: GoalReason | null;
  /** When it is paused, what the model needs from the person, in its words. */
  readonly note?: string | null;
  readonly objective: string;
  readonly token_budget: number;
  /** Tokens its turns have used so far. */
  readonly tokens: number;
  /** Turns it has run. */
  readonly turns: number;
};

/** Why a goal ended. */
export type GoalReason = "met" | "paused" | "stopped" | "budget" | "stalled";

/**
 * A project whose folder isn't there anymore, on the computer it is checked out on, with the
 * sentence that says so.
 */
export type GoneFolder = {
  readonly message: string;
  readonly project: ProjectId;
};

/**
 * How a client groups the person's threads: each under its project, or each under what it is
 * doing (waiting for the person, running, idle).
 */
export type Grouping = "project" | "status";

/** A client's name for one attempt at a turn: 1 to 255 bytes of text. */
export type IdempotencyKey = string;

/** Whether a line was kept, taken out or put in. */
export type LineKind = "same" | "removed" | "added";

/** Identifies one memory: a short statement kept for later threads (`specs/memory.md`). */
export type MemoryId = string;

/** Where a memory belongs: to the person, or to the project it was saved in. */
export type MemoryScope = "personal" | "project";

/** Where in a thread a memory was saved. */
export type MemorySource = {
  readonly seq: Seq;
  readonly thread: ThreadId;
};

/** What a request may carry besides its params, in `params._meta`. */
export type Meta = {
  /**
   * For `turn/start`: the same key for the same thread returns the turn already started
   * instead of starting another, so a client may retry safely.
   */
  readonly idempotency_key?: IdempotencyKey | null;
  /**
   * For `turn/start`: the W3C trace the turn belongs to (`00-<trace id>-<parent id>-<flags>`),
   * recorded with the turn and joined by glave's spans. One that is not one is ignored.
   */
  readonly traceparent?: string | null;
};

/** One model a thread may be sent to. */
export type ModelInfo = {
  /** Its context window, in tokens. */
  readonly context?: number | null;
  /** Whether threads that choose no model use this one. Exactly one model is the default. */
  readonly default: boolean;
  /** What `thread/start` and `turn/start` take as `model`: the name the gateway knows it by. */
  readonly id: string;
  /** Whether it reads images. */
  readonly images?: boolean | null;
  /**
   * Who made it, such as `Anthropic`: as its provider says, else from its id's prefix
   * (`anthropic/…`); absent when neither says.
   */
  readonly maker?: string | null;
  /** The longest answer it gives, in tokens. */
  readonly max_output?: number | null;
  /**
   * Its own name, without its maker's, such as `Claude Haiku 5.5`: the settings', else its
   * provider's, else written from its id as its maker writes it.
   */
  readonly name: string;
  /** What its tokens cost at the first of its providers. */
  readonly price?: TokenPrice | null;
  /**
   * The services that run it, in a person's words (`OpenRouter`, `Anthropic`, a server's
   * address), in the order glave tries them: the first, then each after it only when the
   * one before fails.
   */
  readonly providers?: readonly (string)[];
  /**
   * How it reasons, when it can: the levels of effort it offers, in its provider's names,
   * and as `default` the level its first provider is sent when a thread chooses none, the
   * one that provider's catalog says the model uses unasked. No `default` when glave sends
   * none, and the model reasons as its maker set it.
   */
  readonly reasoning?: Reasoning | null;
};

/**
 * An exact amount: `micros` millionths of one unit of `currency`. `{"micros": 4200,
 * "currency": "USD"}` is $0.0042.
 */
export type Money = {
  readonly currency: Currency;
  readonly micros: number;
};

/** A new project's folder, on the computer glave runs on. */
export type NewFolder = {
  readonly kind: "path";
  readonly path: string;
} | {
  readonly kind: "repository";
  readonly url: string;
} | {
  readonly kind: "empty";
};

/** How the workspace was opened. */
export type Opened = {
  readonly kind: "folder";
  readonly path: string;
} | {
  readonly branch: string;
  readonly kind: "worktree";
  readonly repository: string;
} | {
  readonly at?: string | null;
  readonly kind: "clone";
  readonly url: string;
} | {
  readonly kind: "scratch";
  readonly path: string;
};

/** What started a thread, and who. */
export type Origin = {
  /** Who started it, when that differs from the thread's `for`. */
  readonly by?: Principal | null;
  readonly kind: OriginKind;
  /** An opaque pointer to what started it, such as a schedule or a chat thread. */
  readonly ref?: string | null;
};

/** What kind of thing started a thread. */
export type OriginKind = string;

/** How a turn ended. */
export type Outcome = "completed" | "cancelled" | "failed" | "interrupted" | "limit_reached";

/** A passkey that signs the person in. */
export type PasskeySummary = {
  readonly added: At;
  readonly id: string;
  /** What it is called: the name the browser gave it, else when it was added. */
  readonly name: string;
  /** When it last signed a browser in. */
  readonly used?: At | null;
};

/** The version of one payload type, starting at 1. */
export type PayloadVersion = number;

/**
 * What the agent may do without asking the person (`specs/approvals.md`, "Modes"): the one
 * choice a person makes about it, its mode. Ordered by caution, the most cautious least, so a
 * policy's cap is the highest mode it allows. Each comes to a sandbox and how much asks
 * wherever it runs (`glave-harness`). The names from before the modes were renamed (#739),
 * `read-only` and `workspace`, still read as `ask` and `auto`, so logs and files written then
 * still open; only the new names are written.
 */
export type Permissions = "plan" | "ask" | "auto" | "full-access";

/** A thread's plan: its latest `plan.updated`, by the model or the person. */
export type PlanInfo = {
  /**
   * Whether it waits for the person: proposed in plan mode and not approved yet, to build
   * (`plan/build`), edit (`plan/edit`) or change with a message.
   */
  readonly proposed: boolean;
  /** What it is, in a sentence: "Proposed plan: 5 steps", "Plan: 2 of 5 steps done". */
  readonly sentence: string;
  /** The steps, in order, each with its status. */
  readonly steps: readonly (PlanStep)[];
};

/** How far a step has come: to do, doing, done. */
export type PlanStatus = "pending" | "in_progress" | "completed";

/** One step of a plan. */
export type PlanStep = {
  readonly status: PlanStatus;
  /** What to do, in a line. */
  readonly step: string;
};

/**
 * A reference to a principal: `{"kind": "person", "id": "…"}`. Every kind but `glave` has an
 * id.
 */
export type Principal = {
  readonly id?: PrincipalId | null;
  readonly kind: PrincipalKind;
};

/**
 * Identifies a principal: a person, an agent profile or a group. People, agents and groups
 * share one id space, unique everywhere and never tied to one deployment.
 */
export type PrincipalId = string;

/** What kind of principal acts. */
export type PrincipalKind = string;

/** A project, as its record keeps it. */
export type Project = {
  readonly created_at: At;
  readonly id: ProjectId;
  readonly kind: ProjectKind;
  readonly name: string;
  /** Whose it is: a person, or later a team or an agent. Only they work in it. */
  readonly owner: Principal;
  readonly updated_at: At;
};

/** A project's folder: where its files come from, and where they are checked out. */
export type ProjectFolder = {
  readonly checkout: Checkout;
  readonly source: FolderSource;
};

/** Identifies a project: the boundary for memory, history, files and policy. */
export type ProjectId = string;

/** What a project is. */
export type ProjectKind = "project" | "personal";

/** Identifies one model account a person connected (`provider.connected`). */
export type ProviderId = string;

/** A model account the person connected. */
export type ProviderInfo = {
  /**
   * The key's last four characters, to tell keys apart; absent for a key too short to show
   * any of.
   */
  readonly hint?: string | null;
  readonly id: ProviderId;
  readonly kind: ProviderKind;
  /** The models it offers, the one glave uses by default first. */
  readonly models: readonly (string)[];
  /** The server's API, for a `compatible` account. */
  readonly url?: string | null;
};

/** Which service a model account is with. */
export type ProviderKind = "openai" | "anthropic" | "openrouter" | "compatible";

/** One question. */
export type Question = {
  /** Whether more than one choice may be picked. */
  readonly multiple?: boolean;
  /** Choices to pick from; the person may answer in their own words either way. */
  readonly options?: readonly (Choice)[];
  readonly question: string;
};

/** A message queued to the turn running in its thread, for the model's next call. */
export type QueuedMessage = {
  /**
   * The id of the `message.added` it is recorded as once the model reads it: that
   * `thread/event` says it was read. A `turn/live` `unread` with this id says it never will be.
   */
  readonly id: EventId;
};

/**
 * An event exactly as it is stored and sent. `data` holds the payload's bytes as written;
 * [`crate::decode`] interprets them.
 */
export type RawEvent = {
  readonly at: At;
  /** The payload of `type` at version `v` (`specs/events.md`). */
  readonly data: { readonly [key: string]: unknown };
  readonly glave: number;
  readonly id: EventId;
  readonly seq: Seq;
  readonly thread: ThreadId;
  readonly type: TypeName;
  readonly v: PayloadVersion;
};

/** How a model reasons: the levels of effort it offers, in its service's own names. */
export type Reasoning = {
  /** The level it uses when none is asked for, one of `efforts`, when its service says. */
  readonly default?: string | null;
  /**
   * The levels it offers, as its service lists them, such as `high`, `medium`, `low`, and
   * `none` where reasoning can be turned off. Empty when it offers no choice.
   */
  readonly efforts?: readonly (string)[];
  /** Whether it always reasons. */
  readonly mandatory?: boolean;
};

/** One memory as it is shown: to the model, and to the person. */
export type Remembered = {
  readonly edited_at?: At | null;
  readonly memory: MemoryId;
  readonly saved_at: At;
  readonly scope: MemoryScope;
  /** The thread and `seq` it was saved in. */
  readonly source?: MemorySource | null;
  readonly text: string;
  /** Saved in a thread that had read untrusted content or a secrets file. */
  readonly untrusted_read?: boolean;
  /** 1 when saved, one more with each edit. */
  readonly version: number;
};

/**
 * The pages one reply drew on: each one its turn read with `web_fetch` before it, once, in the
 * order first read. A page that failed to load is none, nor is a search's result the agent
 * did not read.
 */
export type ReplySources = {
  /** The pages, in the order the turn first read each. */
  readonly pages: readonly (WebPage)[];
  /** The `seq` of the reply's `message.added`: the last words of its turn. */
  readonly reply: Seq;
  /** What they are, in a sentence: "Sources: 3 pages". */
  readonly sentence: string;
};

/**
 * A command a thread keeps running in the background, as a client lists it: what it runs,
 * since when, and a sentence saying so (`command/list`).
 */
export type RunningCommand = {
  /** What it runs, as the agent wrote it. */
  readonly command: string;
  /** Which command, for `command/stop`. */
  readonly id: CommandId;
  /** When it started, once the thread has recorded it. */
  readonly started_at?: At | null;
  /** What it is doing, in plain words. */
  readonly summary: string;
};

/** Identifies one schedule: a prompt or goal that runs as a task at set times. */
export type ScheduleId = string;

/** A schedule, as `schedule/list` shows it. */
export type ScheduleInfo = {
  readonly budget: number;
  readonly created_at: At;
  readonly goal?: boolean;
  /** When it last ran: the time that run was due. */
  readonly last?: At | null;
  /** When it runs next; absent once a one-off has run. */
  readonly next?: At | null;
  readonly prompt: string;
  readonly schedule: ScheduleId;
  readonly when: When;
};

/** Whether the person's agent may search the web (`specs/session.md`, "Web search"). */
export type SearchInfo = {
  readonly kind: "never";
  readonly reason: string;
} | {
  readonly detail: string;
  readonly kind: "chosen";
  readonly on: boolean;
  readonly usage?: Usage | null;
};

/** A key or token: sent once, never shown again. */
export type Secret = string;

/**
 * An event's position in its thread, starting at 1 and assigned gap-free by the thread's
 * single writer. This is the order of events; time never is.
 */
export type Seq = number;

/** What the server is. */
export type ServerInfo = {
  /**
   * Where a browser on this computer makes and signs in with passkeys, when the server
   * makes them here rather than at a public origin: `http://localhost:<port>`.
   */
  readonly here?: string | null;
  /**
   * The server's id, where it signs browsers in: the same across restarts, and the one a
   * browser's session must name before the browser presents it.
   */
  readonly id?: string | null;
  /**
   * The modes a thread may choose (`permissions` on `thread/start` and `turn/start`):
   * those the policy leaves, in the order a person is offered them, the recommended first.
   */
  readonly modes: readonly (Permissions)[];
  readonly name: string;
  /** Where people reach the server from elsewhere, if they do: its public origin. */
  readonly origin?: string | null;
  /**
   * What the agent may do in a thread that, and whose project, chose no mode:
   * `--permissions` or `permissions` in `config.toml` (`specs/approvals.md`, "Modes").
   */
  readonly permissions: Permissions;
  /** The protocol versions spoken. */
  readonly protocols: readonly (string)[];
  /**
   * How a browser signs in to it; none where no browser does, as over stdio. A passkey: at a
   * public origin always, a setup link making the first; on this computer once one is made.
   */
  readonly signin?: readonly (SignInWay)[];
  /**
   * Why Auto asks before every change and command here, in a sentence, when it does:
   * no sandbox can run on this computer (Ask first then asks so too), or only one that keeps
   * files as they are.
   */
  readonly unsandboxed?: string | null;
  readonly version: string;
};

/** A person's own settings or connections, by what a client reads to show them. */
export type Setting = "providers" | "credentials" | "connections" | "search" | "grouping" | "awake" | "passkeys";

/** Which threads `thread/list` shows. */
export type Show = "archived" | "active" | "deleted";

/**
 * Signing in to a remote server in the browser: the person opens `url`, its authorization server's
 * page, then the client waits on `flow` with `connection/poll`.
 */
export type SignInLink = {
  /** Names this sign-in to `connection/poll`. */
  readonly flow: string;
  /** The page where the person signs in and approves glave. */
  readonly url: string;
};

/** A way a browser signs in to the server, as `server/discover` says. */
export type SignInWay = "link" | "passkey";

/**
 * Whether a thread is shown: the latest `thread.archived`, `thread.unarchived` or
 * `thread.deleted` decides.
 */
export type Standing = "active" | "archived" | "deleted";

/** What a thread is doing. */
export type Status = "idle" | "running" | "waiting";

/** A task, as the tasks panel shows it. */
export type TaskInfo = {
  /** Tokens the run may use; no limit when absent. */
  readonly budget?: number | null;
  /** What they cost so far, when every call reported a cost. */
  readonly cost?: Money | null;
  /** Milliseconds from its start until now, or until it ended. */
  readonly elapsed_ms: number;
  readonly kind: TaskKind;
  readonly model: string;
  /** How it ended, once it has. */
  readonly outcome?: Outcome | null;
  /** The project its thread is in. */
  readonly project: ProjectId;
  /** The schedule that started it, if one did. */
  readonly schedule?: ScheduleId | null;
  readonly started_at: At;
  readonly status: TaskStatus;
  readonly thread: ThreadId;
  /** The prompt or objective, shortened. */
  readonly title: string;
  /** Tokens used so far, subagents' included. */
  readonly tokens: TokenCounts;
};

/** What kind of work a task is. Background commands the model starts arrive later. */
export type TaskKind = "agent";

/** Whether a task is still going. */
export type TaskStatus = "running" | "finished" | "elsewhere";

/** The files a thread changed, its subagents' changes with its own, and each turn's. */
export type ThreadChanges = {
  /** Every file it changed, in the order first changed. */
  readonly files: readonly (ChangedFile)[];
  /**
   * What they leave out, in a sentence: "Changes made by commands or other tools are not
   * listed."
   */
  readonly note: string;
  /** Each turn that changed files, in order. */
  readonly turns: readonly (TurnChanges)[];
};

/** Identifies one thread: a conversation or task with its own ordered log. */
export type ThreadId = string;

/** A thread, as a list shows it: from the threads view, with what it is doing now. */
export type ThreadSummary = {
  /**
   * How full its context is, as compaction measures it; absent before its first model call
   * and since it was compacted.
   */
  readonly context?: ContextUse | null;
  /**
   * What they cost, when every call reported a cost; absent when one did not: the cost is
   * not reported.
   */
  readonly cost?: Money | null;
  readonly created_at: At;
  /**
   * True when a usage count in `tokens`, and so `cost`, was estimated: a stream ended before
   * its provider reported it.
   */
  readonly estimated?: boolean;
  /** Whose work it is; absent in threads from before it was recorded (the local person). */
  readonly for?: Principal | null;
  readonly id: ThreadId;
  readonly origin: Origin;
  /** How its latest turn ended. */
  readonly outcome?: Outcome | null;
  /** The thread whose call started this one, for a subagent's. */
  readonly parent?: ThreadId | null;
  /**
   * What the agent may do in its next turn: the mode last chosen for it, else its
   * project's, else the server's.
   */
  readonly permissions: Permissions;
  readonly project: ProjectId;
  readonly standing: Standing;
  readonly status: Status;
  /** The title the person gave it, else the first line of their first message. */
  readonly title?: string | null;
  /** Tokens its own model calls used. */
  readonly tokens: TokenCounts;
  /**
   * What its project asks the person on this computer to trust, once the thread was opened
   * or started: shown to them alone, until they answer it.
   */
  readonly trust?: TrustAsk | null;
  readonly turns: number;
  readonly updated_at: At;
  /**
   * Where it works, once it has a workspace, as its latest `workspace.bound` records it: the
   * computer (the one the server runs on, or a worker), the folder its tools act in, and how
   * it got it (its project's folder in place, a worktree on a branch of its own, a clone, or
   * a scratch folder).
   */
  readonly workspace?: WorkspaceBound | null;
};

/**
 * Token counts as inclusive totals with subsets: `input` includes `cache_read` and
 * `cache_write`, and `output` includes `reasoning`. Providers disagree on what their totals
 * include, so adapters normalize before writing.
 */
export type TokenCounts = {
  readonly cache_read: number;
  readonly cache_write: number;
  readonly input: number;
  readonly output: number;
  readonly reasoning: number;
};

/** What a model's tokens cost, in millionths of a US dollar per million tokens. */
export type TokenPrice = {
  /** Input read from the service's cache, when it prices that apart. */
  readonly cache_read?: number | null;
  readonly input: number;
  readonly output: number;
};

/**
 * What a thread's project brings that runs only once the person on this computer trusts it:
 * its tool servers, its hooks and settings that loosen how its commands run
 * (`specs/policy.md`, "Project trust").
 */
export type TrustAsk = {
  /**
   * Names exactly what is asked: `trust/answer` names it back, so only what the person was
   * shown is trusted.
   */
  readonly ask: string;
  /** Each thing in plain words, in the order the project lists them. */
  readonly items: readonly (TrustItem)[];
};

/** The person's answer to a project's ask. */
export type TrustChoice = "trust" | "not_now";

/** One thing a project brings, in plain words. */
export type TrustItem = {
  /**
   * The thing itself, when there is one to show: the command it runs, the address, the
   * model.
   */
  readonly detail?: string | null;
  /** What it does, in a sentence: `Runs a tool server`. */
  readonly text: string;
};

/** The files one turn changed. */
export type TurnChanges = {
  readonly files: readonly (ChangedFile)[];
  /** The `seq` of the turn's `turn.started`. */
  readonly turn: Seq;
};

/**
 * A turn ended (`turn.ended`): how, and what it did and cost, its subagents' work included.
 * It is what a client that ran the turn is answered with too, so every client reads the same.
 * A turn recorded before it held more than `outcome` reads with nothing counted.
 */
export type TurnResult = {
  /**
   * What its model calls cost, when every one of them reported a cost in one currency;
   * absent when one did not: the cost is not reported.
   */
  readonly cost?: Money | null;
  /**
   * True when a usage count was estimated, because a stream ended before the provider
   * reported it.
   */
  readonly estimated?: boolean;
  readonly model_calls?: number;
  readonly outcome: Outcome;
  /** The commands that ran outside the sandbox, each one allowed. */
  readonly outside_sandbox?: number;
  readonly tokens?: TokenCounts;
  readonly tool_calls?: number;
  /**
   * Where its model calls ran, once each in the order they first did, in a person's words:
   * the service, and the provider a service that routes calls passed them on to
   * (`OpenRouter (Anthropic)`).
   */
  readonly via?: readonly (string)[];
  /**
   * The commands that ran with the network the sandbox otherwise kept from them, each one
   * allowed.
   */
  readonly with_network?: number;
};

/**
 * What happened: lowercase dotted segments such as `tool.call.requested`, at most 64 bytes.
 * Each segment is lowercase ASCII letters, digits and underscores; the name starts with a
 * letter.
 */
export type TypeName = string;

/**
 * A passkey a browser signed in with that the server does not know, removed since the
 * sign-in began, for the browser to tell its passkey manager
 * (`PublicKeyCredential.signalUnknownCredential`), which then deletes it.
 */
export type UnknownPasskey = {
  /** Its credential id (`credentialId`), in base64url. */
  readonly credential: string;
  /** The relying party's id (`rpId`). */
  readonly party: string;
};

/** Progress while a turn runs: the live side of `Live`, in a form any transport carries. */
export type Update = {
  readonly kind: "text";
  readonly text: string;
} | {
  readonly kind: "reasoning";
  readonly text: string;
} | {
  readonly kind: "tool_started";
  readonly summary: string;
} | {
  readonly is_error: boolean;
  readonly kind: "tool_finished";
  readonly summary: string;
} | {
  readonly caution?: string | null;
  readonly kind: "tool_declined";
  readonly no_one_there: boolean;
  readonly summary: string;
} | {
  readonly kind: "waiting";
} | {
  readonly error: string;
  readonly kind: "retrying";
  readonly of: number;
  readonly retry: number;
  readonly wait_ms: number;
} | {
  readonly after_tokens: number;
  readonly before_tokens: number;
  readonly kind: "compacted";
} | {
  readonly error: string;
  readonly kind: "compaction_failed";
} | {
  readonly kind: "asked";
  readonly question: CallId;
  readonly questions: readonly (Question)[];
} | {
  readonly approval: CallId;
  readonly kind: "approval_pending";
} | {
  readonly description: string;
  readonly kind: "subagent_started";
  readonly subagent: ThreadId;
} | {
  readonly kind: "subagent_ended";
  readonly ok: boolean;
  readonly subagent: ThreadId;
} | {
  readonly id: EventId;
  readonly kind: "unread";
  readonly reason?: string | null;
} | {
  readonly change: string;
  readonly kind: "memory";
  readonly memory: MemoryId;
  readonly text?: string | null;
};

/** How much a connection was used since this month began (UTC). */
export type Usage = {
  /** The calls the person's agent asked of its tools, refused ones too. */
  readonly calls: number;
  /**
   * The calls, as the person reads them: "412 calls this month", or for web search "412
   * searches this month".
   */
  readonly sentence: string;
};

/** Why a watch ended (`thread/watch`, `thread/list/watch`). */
export type WatchEnd = "unwatched" | "deleted";

/**
 * A web page a call read (`web_fetch`), as its `tool.call.completed` records it in
 * `structured`, under `page`: what a reply drew on, kept apart from the text the model saw.
 */
export type WebPage = {
  /** The title the page gives itself, when it gives one. */
  readonly title?: string | null;
  /** Where it was found, after redirects. */
  readonly url: string;
};

/** When a schedule runs. */
export type When = {
  readonly at: At;
} | {
  readonly cron: string;
};

/** The thread's tools act in this workspace from now on. */
export type WorkspaceBound = {
  readonly computer: ComputerRef;
  readonly opened: Opened;
  /**
   * The workspace root, an absolute path as the computer names it. Tool output and glave's
   * own fields use paths relative to it.
   */
  readonly root: string;
  /** The workspace's id, as its computer named it. */
  readonly workspace: string;
};

